bool test_matrices_equal(double* a, double* b, usize length, double tol)
{
  bool equal = true;

  for (usize i = 0; i < length; ++i)
  {
    double diff = std::abs(a[i] - b[i]);
    if (diff > tol)
    {
      printf("Values %+.17e %+.17e differ by %.1e, more than tolerance %.1e!\n",
              a[i], b[i], diff, tol);
      equal = false;
    }
  }

  return equal;
}


int test_inverse()
{
  double invA_test[100];
  invert_matrix(A, 10, invA_test);

  bool equal = test_matrices_equal(invA, invA_test, 100, 1e-14);

  return (equal) ? 0 : 1;
}


int test_matmul()
{
  double C[200];

  matmul(10, 20, 10, 1., A, B, 0., C);

  bool equal = test_matrices_equal(AxB, C, 200, 1e-18);

  return (equal) ? 0 : 1;
}
